#ifndef MEGAMIX_HID_CAPTURE_H
#define MEGAMIX_HID_CAPTURE_H
#include "bindings.h"
/* Descriptor-driven capture only; no driver sampling/debounce changes. */
static int mu_capture_released(const mh_model *m,const mh_values *v){for(unsigned i=0;i<m->field_count;i++){const mh_field *f=m->fields+i;if(f->kind==MH_BUTTON&&v->valid[i]&&v->value[i])return 0;if(f->kind==MH_HAT&&v->valid[i]&&v->value[i]>=f->minimum&&v->value[i]<=f->maximum)return 0;}return 1;}
static int mu_capture_filtered(const mh_model *m,mh_values *base,const mh_values *v,unsigned control,unsigned stick,unsigned filter,mk_binding *out){for(unsigned pass=0;pass<2;pass++)for(unsigned i=0;i<m->field_count;i++){const mh_field *f=m->fields+i;if((filter==1&&f->kind!=MH_AXIS)||(filter==2&&f->kind==MH_AXIS))continue;if((f->kind==MH_AXIS)!=(pass==1))continue;if(!v->valid[i]||!base->valid[i]){base->value[i]=v->value[i];base->valid[i]=v->valid[i];continue;}mk_binding b={0};b.field=i;if(f->kind==MH_BUTTON&&v->value[i]&&!base->value[i])b.kind=MK_BUTTON;else if(f->kind==MH_HAT&&v->value[i]!=base->value[i]&&v->value[i]>=f->minimum&&v->value[i]<=f->maximum){b.kind=MK_HAT;b.threshold=v->value[i];}else if(f->kind==MH_AXIS){int64_t delta=(int64_t)v->value[i]-base->value[i],span=(int64_t)f->maximum-f->minimum+1;if(f->flags&MH_RELATIVE)delta=v->value[i];else if((f->flags&MH_WRAP)||(control>=9&&!stick)){if(delta>span/2)delta-=span;else if(delta< -span/2)delta+=span;}if(control>=9&&!stick){if(delta>1||delta< -1){b.kind=delta<0?MK_MOTION_NEG:MK_MOTION_POS;b.threshold=1;}}else if(!(f->flags&(MH_RELATIVE|MH_WRAP))&&span>1){if(delta>span/4){b.kind=MK_HIGH;b.threshold=(int32_t)(base->value[i]+span/4);}else if(delta< -span/4){b.kind=MK_LOW;b.threshold=(int32_t)(base->value[i]-span/4);}}}if(b.kind){*out=b;return 1;}}return 0;}
static int mu_capture_control(const mh_model *m,mh_values *base,const mh_values *v,unsigned control,unsigned stick,mk_binding *out){return mu_capture_filtered(m,base,v,control,stick,0,out);}
#endif
